1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.UUID;
4	
5	import net.officefloor.plugin.variable.Val;
6	import org.springframework.samples.petclinic.model.Owner;
7	import org.springframework.samples.petclinic.repository.OwnerRepository;
8	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
9	
10	/**
11	 * Runs after {@link BuildOwner} on {@code POST /api/owners} and assigns the new owner's stable
12	 * {@code householdId}.
13	 *
14	 * <p>When the request opted in via {@code sharesHousehold} true, the new owner joins an existing
15	 * household: the first already-persisted owner in the same household (see {@link OwnerHousehold})
16	 * donates a shared {@code householdId} so both owners carry one identifier (a fresh one is minted and
17	 * stamped onto that donor when it has none yet). Otherwise (not sharing, or sharing with no existing
18	 * household to join) the owner starts its own household and is left with no shared identifier.
19	 *
20	 * <p>The {@code householdId} is a component of the owner's
21	 * {@link org.springframework.samples.petclinic.model.OwnerIdentity} key, so leaving solo
22	 * owners without one is deliberate: duplicate detection then turns on the normalized telephone and
23	 * email, and two owners who merely share a household but differ in telephone remain distinct.
24	 */
25	public class AssignHousehold {
26	
27	    public void service(@Val Owner owner, @Val OwnerFieldsDto request, OwnerRepository ownerRepository) {
28	        if (Boolean.TRUE.equals(request.getSharesHousehold())) {
29	            OwnerHousehold household = OwnerHousehold.of(owner);
30	            for (Owner existing : ownerRepository.findAll()) {
31	                if (household.equals(OwnerHousehold.of(existing))) {
32	                    String householdId = existing.getHouseholdId();
33	                    if (householdId == null) {
34	                        // First time this household is shared: mint one id for both members.
35	                        householdId = UUID.randomUUID().toString();
36	                        existing.setHouseholdId(householdId);
37	                        ownerRepository.save(existing);
38	                    }
39	                    owner.setHouseholdId(householdId);
40	                    return;
41	                }
42	            }
43	        }
44	        // Solo owner (or no household to join): no shared identifier.
45	        owner.setHouseholdId(null);
46	    }
47	}
