9	 * {@link SaveOwner} on {@code POST /api/owners}. Records the new owner's
10	 * {@code householdMemberCount}: the number of members this owner's household has after this
11	 * create, i.e. the existing owners that share the same {@code householdId} plus the new owner
12	 * itself. The owner is still unsaved, so it is counted by the trailing {@code + 1} rather than by
13	 * iterating the repository.
14	 *
15	 * <p>Records the household size for reporting; it no longer affects the membership level, which is
16	 * derived from email presence and {@code namesakeCount} (see {@code MembershipLevel}).
17	 */
18	public class CountHouseholdMembers {
19	
20	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
21	        String householdId = owner.getHouseholdId();
22	        int count = 0;
23	        for (Owner existing : ownerRepository.findAll()) {
24	            if (householdId != null && householdId.equals(existing.getHouseholdId())) {
25	                count++;
26	            }
27	        }
28	        owner.setHouseholdMemberCount(count + 1); // + 1 for this still-unsaved owner
29	    }
30	}
