20	
21	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
22	        owner.setPossibleDuplicate(false);
23	        owner.setPossibleDuplicateOf(null);
24	
25	        String lastName = owner.getLastName();
26	        String postcode = owner.getPostcode();
27	        String telephone = owner.getTelephone();
28	        if (postcode == null || postcode.isBlank()) {
29	            return; // no postcode to match on
30	        }
31	
32	        Owner match = null;
33	        for (Owner existing : ownerRepository.findAll()) {
34	            if (OwnerMatch.equalsIgnoreCase(lastName, existing.getLastName())
35	                    && postcode.equals(existing.getPostcode())
36	                    && !OwnerMatch.equalsIgnoreCase(telephone, existing.getTelephone())) {
37	                if (match == null || existing.getId() < match.getId()) {
38	                    match = existing;
39	                }
40	            }
41	        }
42	        if (match != null) {
43	            owner.setPossibleDuplicate(true);
44	            owner.setPossibleDuplicateOf(match.getId());
