3	/**
4	 * Shared matching helpers for the {@code POST /api/owners} soft-matching steps that scan
5	 * {@code ownerRepository.findAll()} comparing owner name/contact fields (e.g. {@link CountNamesakes},
6	 * {@link CheckPossibleDuplicate}). Keeps the matching semantics defined in one place.
7	 */
8	final class OwnerMatch {
9	
10	    private OwnerMatch() {
11	    }
12	
13	    /** Null-safe, case-insensitive string equality. */
14	    static boolean equalsIgnoreCase(String a, String b) {
15	        return a == null ? b == null : a.equalsIgnoreCase(b);
16	    }
17	}
