1	package org.springframework.samples.petclinic.model;
2	
3	/**
4	 * Derives an owner's numeric membership level, assigned on create.
5	 *
6	 * <p>The level starts at 1, gains 1 when an email is present, gains 1 when the owner's
7	 * {@code namesakeCount} is 0 (the name was unique on create) and is capped at {@link #MAX} (3).
8	 * Level 4 is reserved for tenure and is not awarded here.
9	 *
10	 * <p>This replaces the former string membership tier and is the single source of truth for the
11	 * computation shared by {@code OwnerMapper} (the {@code membershipLevel} response field) and the
12	 * create audit line.
13	 */
14	public final class MembershipLevel {
15	
16	    /** The highest level this rule awards; level 4 is reserved for tenure. */
17	    public static final int MAX = 3;
18	
19	    private MembershipLevel() {
20	    }
21	
22	    /**
23	     * Compute the membership level for an owner.
24	     *
25	     * @param owner the owner; its {@code email} and {@code namesakeCount} drive the result
26	     * @return the level, between 1 and {@link #MAX} inclusive
27	     */
28	    public static int of(Owner owner) {
29	        int level = 1;
30	        if (owner.hasEmail()) {
31	            level++;
32	        }
33	        if (owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0) {
34	            level++;
35	        }
36	        return Math.min(level, MAX);
37	    }
38	}
