2	
3	/**
4	 * Single source of truth for the "E.164 telephone" concept: the validating step converts a submitted
5	 * value to E.164 before it is stored, and the derived {@link OwnerIdentity} normalizes stored values
6	 * the same way when forming an owner's identity key. Keeping the rule here ensures the value that gets
7	 * stored and the value compared for identity can never silently diverge.
8	 */
9	public final class OwnerTelephone {
10	
11	    private OwnerTelephone() {
12	    }
13	
14	    /**
15	     * Convert a raw telephone to E.164 form, or return {@code null} if it cannot form a valid E.164
16	     * number. Spaces, dashes and brackets are stripped. A leading {@code '+'} keeps its country code;
17	     * otherwise country code {@code '+61'} is assumed and a single leading {@code '0'} is dropped from
18	     * the national digits. The result must have 8 to 15 digits after the {@code '+'}.
19	     *
20	     * <p>The national-number length is also checked against the country code: {@code '+61'} (Australia)
21	     * requires 9 national digits and {@code '+1'} (NANP) requires 10. A number whose national part is
22	     * the wrong length for its country code cannot form a valid E.164 number and returns {@code null}.
23	     */
24	    public static String toE164(String value) {
25	        if (value == null) {
26	            return null;
27	        }
28	        // Strip spaces, dashes and brackets (round and square).
29	        String cleaned = value.replaceAll("[\\s()\\[\\]-]", "");
30	        String digits;
31	        if (cleaned.startsWith("+")) {
32	            digits = cleaned.substring(1);
33	        }
34	        else {
35	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
36	            digits = "61" + national;
37	        }
38	        if (!digits.matches("[0-9]{8,15}")) {
39	            return null;
40	        }
41	        if (!nationalLengthValid(digits)) {
42	            return null;
43	        }
44	        return "+" + digits;
45	    }
46	
47	    /**
48	     * Check the national-number length for the known country codes. {@code '+61'} requires 9 national
49	     * digits and {@code '+1'} requires 10; other country codes are not length-checked here.
50	     */
51	    private static boolean nationalLengthValid(String digits) {
52	        if (digits.startsWith("61")) {
53	            return digits.length() - 2 == 9;
54	        }
55	        if (digits.startsWith("1")) {
56	            return digits.length() - 1 == 10;
57	        }
58	        return true;
59	    }
60	}
