final class OwnerMatch {

    private OwnerMatch() {
    }

    /** Null-safe, case-insensitive string equality. */
    static boolean equalsIgnoreCase(String a, String b) {
        return a == null ? b == null : a.equalsIgnoreCase(b);
    }
}

